from core.utils import exponential_backoff, retry_with_backoff

def reprocess_failed(records):
    """Reprocess failed records using exponential backoff."""
    for record in records:
        retry_with_backoff(
            record,
            lambda r: r._service.process(r),
            backoff_fn=exponential_backoff
        )

